\begin{theorem}\label{thm:goodProj}
Let $f:\reals^{m\times n}\rightarrow\reals$ be $\beta$-smooth and convex. Assume $\nabla{}f$ is non-zero over the unit trace-norm ball and fix some $\X^*\in\mX^*$. Let $r$ denote the multiplicity of $\sigma_1(\nabla{}f(\X^*))$, and let $\mu_1,\mu_2,\dots,\mu_{\min\{m,n\}}$ denote the singular values of $\nabla{}f(\X^*)$ (including multiplicities).  Then, for any $\eta >0$ it holds that
\begin{eqnarray}\label{eq:goodProjRes:1}
\delta(\X^*,\eta,r) \geq  \frac{\eta{}(\mu_1-\mu_{r+1})}{(1+1/\sqrt{r})(1+\eta\beta)}.
\end{eqnarray}

%Then, for any $\eta >0$ and for any $\X$ (not necessarily feasible) satisfying $\Vert{\X-\X^*}\Vert_F \leq \delta(\X^*,\eta,r) :=  \frac{\eta{}(\mu_1-\mu_{r+1})}{(1+1/\sqrt{r})(1+\eta\beta)}$ it holds that $\rank\left({\Pi_{\Vert\cdot\Vert_*\leq1}[\X-\eta\nabla{}f(\X)]}\right) \leq r$.

More generally, for any $\eta>0$ and $r'\in\{r,\dots,\min\{m,n\}-1\}$, it holds that 
\begin{eqnarray}\label{eq:goodProjRes:2}
\delta(\X^*,\eta,r') \geq  \frac{\eta(\mu_1-\mu_{r'+1})}{(1+1/\sqrt{r})(1+\eta\beta)}.
\end{eqnarray}

%for any $\X$ satisfying $\Vert{\X-\X^*}\Vert_F  \leq \delta(\X^*,\eta,r') :=  \frac{\eta(\mu_1-\mu_{r'+1})}{(1+1/\sqrt{r})(1+\eta\beta)}$ that  $\rank\left({\Pi_{\Vert\cdot\Vert_*\leq1}[\X-\eta\nabla{}f(\X)]}\right) \leq r'$.

Moreover, for any $\eta >0$ and $r'\in\{r,\dots,\min\{m,n\}-r\}$, it holds that 
\begin{eqnarray}\label{eq:goodProjRes:3}
\delta(\X^*,\eta,r'+r-1) \geq  \frac{\sqrt{r}\eta(\mu_1-\mu_{r'+1})}{2(1+\eta\beta)}.
\end{eqnarray}

%and any $\eta >0$, it holds for any $\X$ satisfying $\Vert{\X-\X^*}\Vert_F  \leq \frac{\sqrt{r}\eta(\mu_1-\mu_{r'+1})}{2(1+\eta\beta)}$ that  $\rank\left({\Pi_{\Vert\cdot\Vert_*\leq1}[\X-\eta\nabla{}f(\X)]}\right) \leq r'' = r'+r-1$.
\end{theorem}

