\begin{lemma}[projection onto the trace-norm ball]\label{lem:traceNormProj}
Fix a parameter $\tau >0$. Let $\X\in\reals^{m\times n}$ and consider its singular-value decomposition $\X = \sum_{i=1}^{\min\{m,n]}\sigma_i\u_i\v_i^{\top}$. If $\Vert{\X}\Vert_* \geq \tau$, then the Euclidean projection of $\X$ onto the trace-norm ball of radius $\tau$ is given by
\begin{eqnarray}\label{eq:traceBallProj}
\Pi_{\Vert{\cdot}\Vert_*\leq \tau}[\X] = \sum_{i=1}^{\min\{m,n\}}\max\{0,\sigma_i-\sigma\}\u_i\v_i^{\top},
%\Pi_{\Vert{\cdot}\Vert_*\leq 1}[\X] = \sum_{i=1}^{\min\{m,n\}}\max\{0,\sigma_i-\sigma\}\u_i\v_i^{\top},
\end{eqnarray}
where $\sigma \geq 0$ is the unique solution to the equation $\sum_{i=1}^{\min\{m,n\}}\max\{0,\sigma_i-\sigma\} = \tau$.
%where $\sigma \geq 0$ is the unique solution to the equation $\sum_{i=1}^{\min\{m,n\}}\max\{0,\sigma_i-\sigma\} = 1$.

Moreover, there exists $r\in\{1,\dots,\min\{m,n\}-1\}$ such that $\sum_{i=1}^r\sigma_i \geq \tau+r\sigma_{r+1}$ if and only if $\rank\left({\Pi_{\Vert\cdot\Vert_*\leq 1}[\X]}\right) \leq r$. 
\end{lemma}

\begin{proof}
The first part of the lemma is a well-known fact, see for instance \cite{Beck17}.
The second part of the lemma comes from the simple observation, that if $\sum_{i=1}^r\sigma_i \geq \tau+r\sigma_{r+1}$ for some $r$, then $\sigma$, as defined in the lemma, must satisfy $\sigma \geq \sigma_{r+1}$, in which case Eq. \eqref{eq:traceBallProj} sets all bottom $(\min\{m,n\}-r)$ components of the SVD of $\X$ to zero, and hence the projection is of rank at most $r$. It is not hard to show using the same reasoning that the reversed direction also holds.
\end{proof}

\begin{lemma}\label{lem:eigsOfOptGrad}
%Assume that $\nabla{}f$ is non-zero over the unit trace-norm ball.
Let $\X^*\in\mX^*$ be any optimal solution and write its singular value decomposition as $\X^* = \sum_{i=1}^r\sigma_i\u_i\v_i^{\top}$. Then, the gradient vector $\nabla{}f(\X^*)$ admits a singular-value decomposition such that the set of pairs of vectors $\{(-\u_i,\v_i)\}_{i=1}^r$ is a set of top singular-vector pairs of $\nabla{}f(\X^*)$ which corresponds to the largest singular value $\sigma_1(\nabla{}f(\X^*))$.
\end{lemma}

\begin{proof}
First, note that if $\nabla{}f(\X^*) = \mathbf{0}$ then the claim holds trivially. Thus, henceforth we consider the case $\nabla{}f(\X^*)\neq\mathbf{0}$.

It suffices to show that for all $i\in\{1,\dots,r\}$ it holds that $-\u_i^{\top}\nabla{}f(\X^*)\v_i = \sigma_1(\nabla{}f(\X^*))$. 

Assume by contradiction that for some $i\in\{1,\dots,r\}$ it holds that  $-\u_i^{\top}\nabla{}f(\X^*)\v_i < \sigma_1(\nabla{}f(\X^*))$. Let $\u,\v$ denote a singular vector pair corresponding to the top singular value $\sigma_1(\nabla{}f(\X^*))$. Observe that for all $\alpha\in(0,\sigma_i]$, the point $\X_{\alpha}:= \X^* + \alpha(-\u\v^{\top}-\u_i\v_i^{\top})$ is a feasible solution to Problem \eqref{eq:optProb}, i.e., $\Vert{\X_{\alpha}}\Vert_*\leq 1$. Moreover, it holds that
\begin{eqnarray*}
(\X_{\alpha}-\X^*)\bullet\nabla{}f(\X^*) &=& \alpha(-\u\v^{\top}-\u_i\v_i^{\top})\bullet\nabla{}f(\X^*) \\
&<& \alpha(-\sigma_1(\nabla{}f(\X^*)) + \sigma_1(\nabla{}f(\X^*))) = 0,
\end{eqnarray*}
which clearly contradicts the optimality of $\X^*$.
\end{proof}

\begin{proof}
Throughout the proof we assume without loss of generality that $m \leq n$.  Fix a step-size $\eta>0$. 

Denote $\Y^* := \X^*-\eta\nabla{}f(\X^*)$ and let $\sigma_1,\dots,\sigma_m$ denote the singular values of $\Y^*$. Let us also denote by $\mu_1,\dots\mu_m$ the singular values of $\nabla{}f(\X^*)$, and  $r^* := \rank(\X^*)$.
From Lemma \ref{lem:eigsOfOptGrad} we can deduce that
\begin{eqnarray}\label{eq:goodProj:0}
\forall i\in[r^*]: \quad \sigma_i &=& \sigma_i(\X^*) + \eta\mu_1; \nonumber \\
 \forall j>r^*: \quad \sigma_j &=& \eta\mu_j.
\end{eqnarray}

For any integer $r'\in\{r,\dots,m\}$ let us define 
\begin{eqnarray*}
\xi(r') = \sum_{i=1}^{r}\sigma_i - r\cdot\sigma_{r'+1} -1.
\end{eqnarray*}


Since $\nabla{}f(\X^*)\neq\mathbf{0}$, it follows that $\sum_{i=1}^{r^*}\sigma_i(\X^*) =\sum_{i=1}^{r}\sigma_i(\X^*) = \Vert{\X^*}\Vert_*=1$, we have that

\begin{eqnarray}\label{eq:goodProj:1}
\xi(r') := \sum_{i=1}^{r}\sigma_i - r\cdot\sigma_{r'+1} -1 \underset{(a)}{=} 1+\eta{}r\mu_1  - r\eta\mu_{r'+1}  - 1= \eta{}r(\mu_1-\mu_{r'+1}),
\end{eqnarray}
where (a) follows from \eqref{eq:goodProj:0}.


Now, given some $\X\in\reals^{m\times n}$, denote $\Y := \X-\eta\nabla{}f(\X)$ and let $\gamma_1,\dots\gamma_m$ denote the singular values of $\Y$. It holds that

\begin{eqnarray}\label{eq:goodProj:2}
\sum_{i=1}^{r}\gamma_i &\underset{(a)}{\geq} &\sum_{i=1}^{r}\sigma_i - \sum_{i=1}^{r}\sigma_i(\Y-\Y^*) \geq \sum_{i=1}^{r}\sigma_i -\sqrt{r\sum_{i=1}^{r}\sigma_i^2(\Y-\Y^*)} \nonumber \\
&\geq& \sum_{i=1}^{r}\sigma_i -\sqrt{r\sum_{i=1}^{m}\sigma_i^2(\Y-\Y^*)} = \sum_{i=1}^{r}\sigma_i  -\sqrt{r}\Vert{\Y-\Y^*}\Vert_F \nonumber \\
&=& \sum_{i=1}^{r}\sigma_i - \sqrt{r}\Vert{\X-\eta\nabla{}f(\X) - \X^* + \eta\nabla{}f(\X^*)}\Vert_F \nonumber \\
&\geq& \sum_{i=1}^{r}\sigma_i - \sqrt{r}\left({\Vert{\X-\X^*}\Vert_F + \eta\Vert{\nabla{}f(\X) - \nabla{}f(\X^*)}\Vert_F}\right) \nonumber \\
&\underset{(b)}{\geq}& \sum_{i=1}^{r}\sigma_i - \sqrt{r}(1+\eta\beta)\Vert{\X-\X^*}\Vert_F,
\end{eqnarray}
where (a) follows from Ky Fan's inequality for the singular values, and (b) follows from the $\beta$-smoothness of $f(\cdot)$.

Also, similarly, using Weyl's inequality, it holds that
\begin{eqnarray}\label{eq:goodProj:3}
\gamma_{r'+1} \leq \sigma_{r'+1} + \sigma_1(\Y-\Y^*) \leq \sigma_{r'+1} + (1+\eta\beta)\Vert{\X-\X^*}\Vert_F.
\end{eqnarray}

Combining Eq. \eqref{eq:goodProj:1}, \eqref{eq:goodProj:2}, \eqref{eq:goodProj:3}, we have that
\begin{eqnarray}\label{eq:goodProj:4}
\sum_{i=1}^{r'}\gamma_i - r'\gamma_{r'+1} &\geq & \sum_{i=1}^r\gamma_i - r\gamma_{r'+1} \nonumber \\
& \geq &
\sum_{i=1}^{r}\sigma_i - \sqrt{r}(1+\eta\beta)\Vert{\X-\X^*}\Vert_F - r\left({\sigma_{r'+1} + (1+\eta\beta)\Vert{\X-\X^*}\Vert_F}\right) \nonumber\\
&=& \sum_{i=1}^{r}(\sigma_i-\sigma_{r'+1}) -(r+\sqrt{r})(1+\eta\beta)\Vert{\X-\X^*}\Vert_F \nonumber\\
&=& 1 + \xi(r') - (r+\sqrt{r})(1+\eta\beta)\Vert{\X-\X^*}\Vert_F.
\end{eqnarray}


Thus, it follows that if $\X$ satisfies:
\begin{eqnarray*}%\label{eq:goodProj:5}
\Vert{\X-\X^*}\Vert_F \leq  \frac{\xi(r')}{(r+\sqrt{r})(1+\eta\beta)} = \frac{\eta(\mu_1-\mu_{r'+1})}{(1+1/\sqrt{r})(1+\eta\beta)},
\end{eqnarray*}
we have that $\sum_{i=1}^{r'}\gamma_i - r'\gamma_{r'+1} \geq 1$, which implies via Lemma \ref{lem:traceNormProj} that $\rank\left({\projgrad_{\eta}(\X)}\right)\leq r$. This proves \eqref{eq:goodProjRes:1}, \eqref{eq:goodProjRes:2}.

Alternatively, for any $r'' \geq r' + r-1$, using the more general version of Weyl's inequality, we can replace Eq. \eqref{eq:goodProj:3} with
\begin{eqnarray}\label{eq:goodProj:6}
\gamma_{r''+1} &\leq & \sigma_{r'+1} + \sigma_{r''-r'+1}(\Y-\Y^*) = \sigma_{r'+1} + \sqrt{\sigma^2_{r''-r'+1}(\Y-\Y^*)} \nonumber \\
& \leq & \sigma_{r'+1} + \sqrt{\frac{1}{r''-r'+1}\Vert{\Y-\Y^*}\Vert_F^2} \nonumber \\
&\leq &\sigma_{r'+1} + \frac{1}{\sqrt{r''-r'+1}}(1+\eta\beta)\Vert{\X-\X^*}\Vert_F.
\end{eqnarray}

Thus, similarly to Eq. \eqref{eq:goodProj:4}, but replacing Eq. \eqref{eq:goodProj:3} with Eq. \eqref{eq:goodProj:4}, we obtain
\begin{eqnarray*}
\sum_{i=1}^{r''}\gamma_i - r''\gamma_{r''+1} &\geq &\sum_{i=1}^{r}\gamma_i - r\gamma_{r''+1}\geq \sum_{i=1}^{r}\sigma_i  - \sqrt{r}(1+\eta\beta)\Vert{\X-\X^*}\Vert_F \nonumber \\
&&- r\left({\sigma_{r'+1} + \frac{1}{\sqrt{r''-r'+1}}(1+\eta\beta)\Vert{\X-\X^*}\Vert_F}\right) \nonumber \\
&=& \sum_{i=1}^{r}(\sigma_i-\sigma_{r'+1}) - \left({\sqrt{r} + \frac{r}{\sqrt{r''-r'+1}}}\right)(1+\eta\beta)\Vert{\X-\X^*}\Vert_F \nonumber \\
&=& 1 + \xi(r') - \left({\sqrt{r} + \frac{r}{\sqrt{r''-r'+1}}}\right)(1+\eta\beta)\Vert{\X-\X^*}\Vert_F.
\end{eqnarray*}

In particular, for $r'' = r'+r-1$, we obtain
\begin{eqnarray*}
\sum_{i=1}^{r''}\gamma_i - r''\gamma_{r''+1} \geq 1 + \xi(r') - 2\sqrt{r}(1+\eta\beta)\Vert{\X-\X^*}\Vert_F.
\end{eqnarray*}

Thus, it follows that if $\X$ satisfies:
\begin{eqnarray*}
\Vert{\X-\X^*}\Vert_F \leq \frac{\xi(r')}{2\sqrt{r}(1+\eta\beta)} = \frac{r\eta(\mu_1-\mu_{r'+1})}{2\sqrt{r}(1+\eta\beta)} = \frac{\sqrt{r}\eta(\mu_1-\mu_{r'+1})}{2(1+\eta\beta)},
\end{eqnarray*}
we have that  $\rank\left({\projgrad_{\eta}(\X)}\right)\leq r''$, which proves \eqref{eq:goodProjRes:3}.

\end{proof}

